<?php
use App\Http\Controllers\Auth\EmailPasswordResetController;use App\Http\Controllers\Auth\EmailVerificationOtpController;use App\Http\Controllers\Auth\GoogleAuthController;use App\Http\Controllers\DashboardController;use App\Http\Controllers\MemberCouponController;use App\Http\Controllers\OrderController;use App\Http\Controllers\PayPalController;use App\Http\Controllers\ProductController;use App\Http\Controllers\ReturnRequestController;use App\Http\Controllers\VatInvoiceController;use Illuminate\Support\Facades\Route;use Inertia\Inertia;
Route::middleware('client')->group(function():void{Route::get('/',[ProductController::class,'home'])->name('home');Route::get('/products',[ProductController::class,'index'])->name('products.index');Route::match(['get','post'],'/products/catalog',[ProductController::class,'catalog'])->name('products.catalog');Route::get('/products/{slug}',[ProductController::class,'show'])->name('products.show');Route::get('/cart',fn()=>Inertia::render('Cart'))->name('cart.index');Route::get('/checkout',fn()=>Inertia::render('Checkout'))->middleware(['auth','otp.verified'])->name('checkout.index');Route::middleware('guest')->group(function():void{Route::get('/auth/google',[GoogleAuthController::class,'redirect'])->name('google.redirect');Route::get('/auth/google/callback',[GoogleAuthController::class,'callback'])->name('google.callback');Route::get('/auth/google/check-email',[GoogleAuthController::class,'checkEmail'])->name('google.check-email');Route::get('/forgot-password',[EmailPasswordResetController::class,'showRequest'])->name('password.email.request');Route::post('/forgot-password',[EmailPasswordResetController::class,'requestCode'])->middleware('throttle:3,5')->name('password.email.send');Route::get('/forgot-password/verify',[EmailPasswordResetController::class,'showVerify'])->name('password.email.verify');Route::post('/forgot-password/verify',[EmailPasswordResetController::class,'verifyCode'])->middleware('throttle:6,1')->name('password.email.verify.submit');Route::post('/forgot-password/verify/resend',[EmailPasswordResetController::class,'resendCode'])->middleware('throttle:3,5')->name('password.email.verify.resend');Route::get('/forgot-password/reset',[EmailPasswordResetController::class,'showReset'])->name('password.email.reset');Route::post('/forgot-password/reset',[EmailPasswordResetController::class,'resetPassword'])->middleware('throttle:6,1')->name('password.email.reset.submit');});Route::middleware('auth')->group(function():void{Route::get('/verify-email-otp',[Email